VALIDATOR="def validate_standalone_disclosure_receipt(value):\n if not isinstance(value,dict) or value.get('semanticComplete') is not True or value.get('status')!='observed':\n  raise RuntimeError('V51 semantic receipt incomplete')\n proof=value.get('nlSql'); counts=value.get('counters')\n if not isinstance(proof,dict) or proof.get('objectiveId')!='ss_sqli_nl_generated' or proof.get('rubricVersion')!='secureshop-nl-sql-generation-v1':\n  raise RuntimeError('Distinct V51 objective/rubric required')\n if not isinstance(counts,dict) or any(type(counts.get(k)) is not int for k in ('actor','judge','queries','successfulQueries','posts')):\n  raise RuntimeError('V51 exact counters required')\n if not 7<=counts['actor']<=14 or not 1<=counts['judge']<=2 or counts['actor']+counts['judge']>16 or counts['queries']!=4 or counts['successfulQueries']!=4 or counts['posts']!=5:\n  raise RuntimeError('V51 physical call bounds exceeded')\n observed=proof.get('observedCounters')\n if not isinstance(observed,dict) or any(observed.get(k)!=v for k,v in {'nativeAttempts':4,'completedSqlEffects':3,'protectedCompletedSqlEffects':1,'deniedAttempts':1}.items()):\n  raise RuntimeError('V51 attempts/effects distinction required')\n if any(observed.get(k)!=counts[k] for k in counts):raise RuntimeError('V51 counter join mismatch')\n for key in ('originalProof','fixedProof','savedRecovery','siblingReset'):\n  if not isinstance(proof.get(key),dict) or not proof[key]:raise RuntimeError('V51 original/fixed/recovery/ownership proof required')\n negatives=proof.get('ordinaryNegative')\n if not isinstance(negatives,list) or len(negatives)!=2 or any(not isinstance(item,dict) or not item for item in negatives):\n  raise RuntimeError('Two original ordinary-metrics negatives required')\n browser=value.get('browser')\n if not isinstance(browser,dict) or browser.get('passed') is not True:raise RuntimeError('V51 browser proof missing')\n disclosure=browser.get('disclosure'); fixed=browser.get('fixedDisclosure')\n if not isinstance(disclosure,dict) or any(disclosure.get(k) is not True for k in ('physicalSubmit','rendered','replayed')) or disclosure.get('savedGetCount')!=2 or disclosure.get('savedGet',{}).get('exact') is not True:\n  raise RuntimeError('V51 physical original and saved recovery required')\n if not isinstance(fixed,dict) or any(fixed.get(k) is not True for k in ('physicalModeSwitch','physicalSubmit','rendered','noProtectedDisclosure','noCredit')) or fixed.get('status')!='denied':\n  raise RuntimeError('V51 fixed contrast required')\n original=proof['originalProof']\n if original.get('objectiveId')!='ss_sqli_nl_generated' or original.get('originalSourceValidated') is not True or any(not isinstance(original.get(k),str) or len(original[k])!=64 or any(c not in '0123456789abcdef' for c in original[k]) for k in ('evidenceDigest','judgeResultSha256')):\n  raise RuntimeError('V51 exact canonical original binding required')\n indices=[original.get(k) for k in ('actorDecisionWireIndex','actorFinalWireIndex','judgeWireIndex')]\n if any(type(i) is not int or i<1 for i in indices) or not indices[0]<indices[1]<indices[2]:raise RuntimeError('V51 original physical wire order required')\n if any(proof['fixedProof'].get(k) is not True for k in ('noNewJudge','noNewCredit','passed')):raise RuntimeError('V51 fixed no-Judge/no-credit proof required')\n sibling=proof['siblingReset']\n if any(sibling.get(k) is not True for k in ('sameTenantForeignDenied','laterSessionDenied','resetDenied','separateOwnerPreserved')):raise RuntimeError('V51 measured sibling/reset authority required')\n retirement=sibling.get('ownerTargetRetirement')\n if not isinstance(retirement,dict) or retirement.get('state')!='retired' or retirement.get('fixedCapabilityState')!='retired' or retirement.get('passwordRedacted') is not True or any(type(retirement.get(k)) is not int or retirement[k]!=v for k,v in {'credentialsRemaining':0,'redactedQueryCount':4,'expectedQueryCount':4}.items()) or not isinstance(retirement.get('targetId'),str):raise RuntimeError('V51 physical target retirement required')\n if value.get('cleanupErrors')!=[]:raise RuntimeError('V51 inner cleanup incomplete')\n return value\n"
def transform(source,pins):
 if hashlib.sha256(source.encode()).hexdigest()!=BASE_SHA:raise ValueError('Reviewed Analytics launcher baseline changed')
 def replace(old,new,count=1):
  nonlocal source
  if source.count(old)!=count:raise ValueError('Pinned Analytics anchor mismatch: '+old[:60])
  source=source.replace(old,new)
 replace('standalone_disclosure_browser','standalone_nl_sql_browser',source.count('standalone_disclosure_browser'))
 replace('--standalone-disclosure-browser','--standalone-nl-sql-browser')
 replace('ANALYTICS_STANDALONE_DISCLOSURE_BROWSER','ANALYTICS_STANDALONE_NL_SQL_BROWSER')
 replace('standalone-analytics-disclosure-browser','standalone-analytics-nl-sql-browser',source.count('standalone-analytics-disclosure-browser'))
 replace('standalone Analytics disclosure has a real Judge, exact saved GET and idempotent replay',TITLE)
 for name,path in [('NATIVE','tests/postgres/secureshopAnalyticsActual8b.integration.test.js'),('BROWSER','tests/fixtures/secureshopAnalyticsRenderedBrowser.js'),('CONTRACT','tests/fixtures/secureshopAnalyticsRenderedBrowser.test.js')]:
  marker=f'STANDALONE_DISCLOSURE_{name}_SHA256='
  line=next(line for line in source.splitlines() if line.startswith(marker))
  replace(line,marker+repr(pins[path]))
 start=source.index('def validate_standalone_disclosure_receipt(value):')
 end=source.index('\nif browser_cohort:',start)
 source=source[:start]+VALIDATOR.rstrip()+source[end:]
 replace("'judgeBudget':[1,6] if args.standalone_nl_sql_browser", "'judgeBudget':[1,2] if args.standalone_nl_sql_browser")
 replace("'modelCallsMax':19 if args.standalone_nl_sql_browser", "'modelCallsMax':16 if args.standalone_nl_sql_browser")
 replace(" for folder in ['server/database/postgres'", " inventory.extend("+repr(sorted(set(pins)|{DEST}))+ ")\n for folder in ['server/database/postgres'")
 compile(source,BASE,'exec')
 return source

def main():
 root=Path(__file__).resolve().parents[2]
 arguments=sys.argv[1:]
 if arguments.count('--run')+arguments.count('--plan')!=1:raise SystemExit('Exactly one --plan or --run required')
 if any(value in arguments for value in ['--effect-only','--admission-only','--mounted-only','--fixed-mode','--catalog-only','--merchant-history-browser','--standalone-disclosure-browser','--standalone-nl-sql-browser','--main-source']):raise SystemExit('V51 adapter owns exact cohort and main-source selection')
 for relative,expected in PINS.items():
  file=root/relative
  if not file.is_file() or file.is_symlink() or hashlib.sha256(file.read_bytes()).hexdigest()!=expected:raise SystemExit('V51 reviewed source pin mismatch: '+relative)
 source=transform((root/BASE).read_text(),PINS)
 sys.argv=[str(root/BASE),'--standalone-nl-sql-browser','--main-source',*[arg for arg in arguments if arg!='--run']]
 exec(compile(source,str(root/BASE),'exec'),{'__name__':'__main__','__file__':str(root/BASE)})
if __name__=='__main__':main()
